public class MainActivity extends Activity {
 WebView web,printWeb; boolean unlocked=false,loaded=false,external=false;String launchNote="",pendingNote="",pendingKind="",pendingPassword="";byte[] exportBytes;String exportMime;
 final ExecutorService worker=Executors.newSingleThreadExecutor();
 final Map<String,byte[]> staged=new HashMap<>();
 android.content.SharedPreferences prefs;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(120,44,67));getWindow().setNavigationBarColor(Color.rgb(120,44,67));prefs=getSharedPreferences("security",MODE_PRIVATE);launchNote=getIntent().getStringExtra("note");buildWeb();}
 void buildWeb(){web=new WebView(this);web.setBackgroundColor(Color.rgb(248,245,240));WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setBlockNetworkLoads(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSupportMultipleWindows(false);web.addJavascriptInterface(new Bridge(),"Native");web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest req){if(req.getUrl().toString().startsWith("file:///android_asset/"))return false;return true;}});android.widget.FrameLayout frame=new android.widget.FrameLayout(this);frame.addView(web,new android.widget.FrameLayout.LayoutParams(-1,-1));frame.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets.consumeSystemWindowInsets();});setContentView(frame);web.setVisibility(View.INVISIBLE);}
 @Override protected void onResume(){super.onResume();if(!unlocked){if(prefs.contains("pin"))askPin();else unlock();}}
 void unlock(){unlocked=true;web.setVisibility(View.VISIBLE);if(!loaded){loaded=true;web.loadUrl("file:///android_asset/index.html");}}
 @Override protected void onStop(){super.onStop();if(!external&&prefs.contains("pin")){unlocked=false;web.setVisibility(View.INVISIBLE);}}
 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);launchNote=i.getStringExtra("note");if(unlocked&&loaded&&launchNote!=null)js("window.openNotification("+JSONObject.quote(launchNote)+")");}
 void askPin(){if(isFinishing())return;EditText e=new EditText(this);e.setInputType(18);e.setHint("PIN");e.setPadding(32,24,32,24);AlertDialog d=new AlertDialog.Builder(this).setTitle("SadieNotes kilitli").setMessage("Notlarına erişmek için PIN'ini gir.").setView(e).setCancelable(false).setNegativeButton("Kapat",(a,b)->finish()).setPositiveButton("Aç",null).create();d.setOnShowListener(a->d.getButton(-1).setOnClickListener(v->{long until=prefs.getLong("blockedUntil",0);if(System.currentTimeMillis()<until){e.setError("30 saniye bekleyip tekrar dene.");return;}String pin=e.getText().toString();d.getButton(-1).setEnabled(false);worker.execute(()->{boolean ok=false;try{ok=MessageDigest.isEqual(Crypto.derive(pin,Crypto.un64(prefs.getString("salt",""))),Crypto.un64(prefs.getString("pin","")));}catch(Exception ex){}final boolean pass=ok;runOnUiThread(()->{d.getButton(-1).setEnabled(true);if(pass){prefs.edit().putInt("failures",0).remove("blockedUntil").apply();d.dismiss();unlock();}else{int fails=prefs.getInt("failures",0)+1;prefs.edit().putInt("failures",fails).putLong("blockedUntil",fails>=5?System.currentTimeMillis()+30000:0).apply();e.setText("");e.setError("PIN yanlış.");}});});}));d.show();}
 void js(String code){runOnUiThread(()->{if(web!=null)web.evaluateJavascript(code,null);});}
 void toast(String s){runOnUiThread(()->Toast.makeText(this,s,Toast.LENGTH_LONG).show());}
 static byte[] read(InputStream in,int limit)throws Exception{try(InputStream input=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=input.read(b))!=-1){if(out.size()+n>limit)throw new IOException("Dosya boyut sınırını aşıyor");out.write(b,0,n);}return out.toByteArray();}}
 File dataFile(){return new File(getFilesDir(),"notes.bin");}
 synchronized String readState()throws Exception{if(!dataFile().exists()&&!new File(dataFile()+".bak").exists())return "";return new String(Crypto.decrypt(read(new AtomicFile(dataFile()).openRead(),16*1024*1024)),StandardCharsets.UTF_8);}
 synchronized void saveState(String raw)throws Exception{if(raw.getBytes(StandardCharsets.UTF_8).length>12*1024*1024)throw new IOException("Not verisi 12 MB sınırını aşıyor. Ekleri dosya olarak ekle.");JSONObject obj=new JSONObject(raw);if(obj.optInt("version")!=1||!(obj.opt("notes") instanceof JSONArray))throw new IOException("Geçersiz not verisi");AtomicFile file=new AtomicFile(dataFile());FileOutputStream stream=null;try{stream=file.startWrite();stream.write(Crypto.encrypt(raw.getBytes(StandardCharsets.UTF_8)));file.finishWrite(stream);}catch(Exception e){if(stream!=null)file.failWrite(stream);throw e;}}
 static File attachment(Context c,String id)throws Exception{if(!id.matches("[a-f0-9-]{36}"))throw new IOException("Invalid attachment");File dir=new File(c.getFilesDir(),"attachments");dir.mkdirs();return new File(dir,id+".bin");}
 String fileName(Uri uri){String name="Dosya";try(android.database.Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}catch(Exception e){}return name==null?"Dosya":name.substring(0,Math.min(180,name.length()));}
 void choose(int code,String mime){external=true;try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType(mime).addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,code);}catch(Exception e){external=false;toast("Dosya seçici açılamadı.");}}
 void export(String name,String mime,byte[] bytes){exportBytes=bytes;exportMime=mime;external=true;try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(mime).addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,name),20);}catch(Exception e){external=false;exportBytes=null;toast("Kaydetme ekranı açılamadı.");}}
 class Bridge {
  @JavascriptInterface public String loadData(){if(!unlocked)return "{\"ok\":false,\"error\":\"Kilitli\"}";try{String raw=readState();return new JSONObject().put("ok",true).put("data",raw).toString();}catch(Exception e){return "{\"ok\":false,\"error\":\"Şifreli not verisi okunamadı. Verinin üzerine yazılmadı. Yedekten geri yükleyebilirsin.\"}";}}
  @JavascriptInterface public String saveData(String raw){if(!unlocked)return "Kilitli";try{saveState(raw);return "";}catch(Exception e){return "Kayıt başarısız: "+e.getMessage();}}
  @JavascriptInterface public String launchNote(){return launchNote==null?"":launchNote;}
  @JavascriptInterface public String status(){return "{\"pin\":"+prefs.contains("pin")+",\"notifications\":"+(Build.VERSION.SDK_INT<33||checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED)+"}";}
  @JavascriptInterface public void setPin(){if(!unlocked)return;runOnUiThread(()->{LinearLayout box=new LinearLayout(MainActivity.this);box.setOrientation(1);box.setPadding(30,10,30,10);EditText one=new EditText(MainActivity.this),two=new EditText(MainActivity.this);one.setHint("Yeni PIN (en az 6 rakam)");two.setHint("PIN'i tekrar gir");one.setInputType(18);two.setInputType(18);box.addView(one);box.addView(two);AlertDialog d=new AlertDialog.Builder(MainActivity.this).setTitle("Uygulamayı kilitle").setMessage("PIN'i unutursan kurtarma yoktur. Önce şifreli yedek al.").setView(box).setNegativeButton("Vazgeç",null).setPositiveButton("Kaydet",null).create();d.setOnShowListener(a->d.getButton(-1).setOnClickListener(v->{String pin=one.getText().toString();if(!pin.matches("[0-9]{6,20}")||!pin.equals(two.getText().toString())){two.setError("PIN'ler aynı ve 6–20 rakam olmalı.");return;}d.getButton(-1).setEnabled(false);worker.execute(()->{try{byte[] salt=Crypto.random(16);prefs.edit().putString("salt",Crypto.b64(salt)).putString("pin",Crypto.b64(Crypto.derive(pin,salt))).putInt("failures",0).remove("blockedUntil").commit();runOnUiThread(()->d.dismiss());toast("PIN etkin. Uygulama arka plana geçince kilitlenir.");js("window.onSecurityChanged()");}catch(Exception ex){toast("PIN kaydedilemedi.");runOnUiThread(()->d.getButton(-1).setEnabled(true));}});}));d.show();});}
  @JavascriptInterface public void removePin(){if(!unlocked)return;runOnUiThread(()->new AlertDialog.Builder(MainActivity.this).setTitle("PIN kaldırılsın mı?").setMessage("Cihazındaki notların şifreli saklanmaya devam eder.").setNegativeButton("Vazgeç",null).setPositiveButton("Kaldır",(d,w)->{prefs.edit().remove("pin").remove("salt").remove("blockedUntil").apply();js("window.onSecurityChanged()");}).show());}
  @JavascriptInterface public void lock(){if(!unlocked)return;runOnUiThread(()->{if(prefs.contains("pin")){unlocked=false;web.setVisibility(View.INVISIBLE);askPin();}else toast("Önce Ayarlar'dan PIN oluştur.");});}
  @JavascriptInterface public void setReminders(String raw){if(!unlocked)return;runOnUiThread(()->{try{JSONArray array=new JSONArray(raw);ReminderReceiver.replace(MainActivity.this,array);if(array.length()>0&&Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},8);}catch(Exception e){toast("Hatırlatıcılar ayarlanamadı.");}});}
  @JavascriptInterface public void pickAttachment(String note){if(!unlocked)return;pendingNote=note;runOnUiThread(()->choose(21,"*/*"));}
  @JavascriptInterface public String attachmentData(String id){if(!unlocked)return "";try{byte[] data=Crypto.decrypt(read(new FileInputStream(attachment(MainActivity.this,id)),21*1024*1024));if(data.length>5*1024*1024)return "";return Crypto.b64(data);}catch(Exception e){return "";}}
  @JavascriptInterface public void openAttachment(String id,String name,String mime){if(!unlocked)return;runOnUiThread(()->{try{attachment(MainActivity.this,id);Uri uri=new Uri.Builder().scheme("content").authority("com.sadienotes.app.attachments").appendPath(id).appendPath(name).appendQueryParameter("mime",mime).build();Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,mime).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(intent,"Dosyayı aç"));}catch(Exception e){toast("Bu dosyayı açabilecek uygulama bulunamadı.");}});}
  @JavascriptInterface public void pruneAttachments(String raw){if(!unlocked)return;worker.execute(()->{try{Set<String> ids=new HashSet<>();JSONArray list=new JSONArray(raw);for(int i=0;i<list.length();i++)ids.add(list.getString(i)+".bin");File dir=new File(getFilesDir(),"attachments");File[] files=dir.listFiles();if(files!=null)for(File f:files)if(!ids.contains(f.getName()))f.delete();}catch(Exception e){}});}
  @JavascriptInterface public void exportText(String name,String mime,String raw){if(!unlocked)return;if(!Arrays.asList("text/plain","text/markdown","text/html","application/json").contains(mime))return;runOnUiThread(()->export(name.replaceAll("[\\\\/:*?\"<>|]","_"),mime,raw.getBytes(StandardCharsets.UTF_8)));}
  @JavascriptInterface public void openLink(String url){if(!unlocked||!url.matches("(?i)^(https?://|mailto:).+"))return;runOnUiThread(()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){toast("Bağlantı açılamadı.");}});}
  @JavascriptInterface public void share(String title,String text){if(!unlocked)return;runOnUiThread(()->{try{startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_SUBJECT,title).putExtra(Intent.EXTRA_TEXT,text),"Notu paylaş"));}catch(Exception e){toast("Paylaşım açılamadı.");}});}
  @JavascriptInterface public void print(String title,String html){if(!unlocked)return;runOnUiThread(()->{printWeb=new WebView(MainActivity.this);printWeb.getSettings().setJavaScriptEnabled(false);printWeb.getSettings().setBlockNetworkLoads(true);printWeb.getSettings().setAllowFileAccess(false);printWeb.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView v,String u){try{((PrintManager)getSystemService(PRINT_SERVICE)).print(title,v.createPrintDocumentAdapter(title),new PrintAttributes.Builder().build());}catch(Exception e){toast("Yazdırma açılamadı.");}}});printWeb.loadDataWithBaseURL(null,html,"text/html","UTF-8",null);});}
  @JavascriptInterface public void exportBackup(String password){if(!unlocked)return;if(!password.isEmpty()&&password.length()<8){toast("Yedek parolası en az 8 karakter olmalı.");return;}worker.execute(()->{try{String data=readState();if(data.isEmpty())throw new IOException();JSONObject bundle=new JSONObject().put("format","SadieNotesBackup").put("version",1).put("data",new JSONObject(data));JSONObject files=new JSONObject();JSONArray notes=bundle.getJSONObject("data").getJSONArray("notes");long total=0;for(int i=0;i<notes.length();i++){JSONArray at=notes.getJSONObject(i).optJSONArray("attachments");if(at==null)continue;for(int j=0;j<at.length();j++){String id=at.getJSONObject(j).getString("id");if(!files.has(id)){byte[] bytes=Crypto.decrypt(read(new FileInputStream(attachment(MainActivity.this,id)),21*1024*1024));total+=bytes.length;if(total>40*1024*1024)throw new IOException("Yedek 40 MB ek sınırını aşıyor.");files.put(id,Crypto.b64(bytes));}}}bundle.put("files",files);byte[] result=Crypto.backup(bundle.toString(),password).getBytes(StandardCharsets.UTF_8);runOnUiThread(()->export("SadieNotes-"+new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date())+(password.isEmpty()?"-backup.json":"-encrypted.snb"),"application/json",result));}catch(OutOfMemoryError e){toast("Yedek için bellek yetersiz. Daha az ek içeren bir yedek dene.");}catch(Exception e){toast("Yedek oluşturulamadı: "+e.getMessage());}});}
  @JavascriptInterface public void importFile(String kind,String password){if(!unlocked)return;pendingKind=kind;pendingPassword=password;runOnUiThread(()->choose(22,"*/*"));}
  @JavascriptInterface public String commitRestore(String raw){if(!unlocked)return "Kilitli";try{for(Map.Entry<String,byte[]> item:staged.entrySet()){try(FileOutputStream out=new FileOutputStream(attachment(MainActivity.this,item.getKey()))){out.write(Crypto.encrypt(item.getValue()));}}saveState(raw);staged.clear();return "";}catch(Exception e){return "Geri yüklenemedi: "+e.getMessage();}}
 }
 @Override protected void onActivityResult(int req,int result,Intent intent){super.onActivityResult(req,result,intent);external=false;if(result!=RESULT_OK||intent==null||intent.getData()==null){exportBytes=null;pendingPassword="";return;}Uri uri=intent.getData();if(req==20){byte[] payload=exportBytes;exportBytes=null;worker.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null||payload==null)throw new IOException();out.write(payload);toast("Dosya kaydedildi.");}catch(Exception e){toast("Dosya kaydedilemedi.");}});}else if(req==21){final String note=pendingNote;worker.execute(()->{try{byte[] bytes=read(getContentResolver().openInputStream(uri),20*1024*1024);String id=UUID.randomUUID().toString(),name=fileName(uri),mime=getContentResolver().getType(uri);if(mime==null)mime="application/octet-stream";try(FileOutputStream out=new FileOutputStream(attachment(MainActivity.this,id))){out.write(Crypto.encrypt(bytes));}JSONObject obj=new JSONObject().put("id",id).put("name",name).put("mime",mime).put("size",bytes.length);js("window.onAttachment("+JSONObject.quote(note)+","+obj+")");}catch(Exception e){toast("Ek eklenemedi: "+e.getMessage());}});}else if(req==22){final String kind=pendingKind,password=pendingPassword;pendingPassword="";worker.execute(()->{try{String raw=new String(read(getContentResolver().openInputStream(uri),120*1024*1024),StandardCharsets.UTF_8);if(!"backup".equals(kind)){js("window.onTextImport("+JSONObject.quote(fileName(uri))+","+JSONObject.quote(raw)+")");return;}JSONObject bundle=new JSONObject(Crypto.unbackup(raw,password));if(!"SadieNotesBackup".equals(bundle.optString("format"))||bundle.optInt("version")!=1)throw new IOException("Desteklenmeyen yedek");JSONObject data=bundle.getJSONObject("data"),files=bundle.optJSONObject("files");if(files==null)files=new JSONObject();staged.clear();long total=0;Map<String,String> mapping=new HashMap<>();Iterator<String> keys=files.keys();while(keys.hasNext()){String old=keys.next();byte[] bytes=Crypto.un64(files.getString(old));total+=bytes.length;if(bytes.length>20*1024*1024||total>40*1024*1024)throw new IOException("Ek sınırı aşıldı");String id=UUID.randomUUID().toString();mapping.put(old,id);staged.put(id,bytes);}JSONArray notes=data.getJSONArray("notes");for(int i=0;i<notes.length();i++){JSONArray at=notes.getJSONObject(i).optJSONArray("attachments");if(at!=null)for(int j=0;j<at.length();j++){JSONObject f=at.getJSONObject(j);String id=mapping.get(f.getString("id"));if(id==null)throw new IOException("Eksik ek dosyası");f.put("id",id);}}js("window.onBackupImport("+data+")");}catch(OutOfMemoryError e){staged.clear();toast("Yedek için bellek yetersiz. Mevcut notların değiştirilmedi.");}catch(Exception e){staged.clear();toast("İçe aktarılamadı. Dosya, parola veya biçim geçersiz: "+e.getClass().getSimpleName());}});}}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==8&&!(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED))toast("Bildirim izni verilmedi; hatırlatıcı bildirimi gösterilemez.");}
 @Override public void onBackPressed(){if(unlocked&&loaded)web.evaluateJavascript("window.appBack?window.appBack():false",result->{if(!"true".equals(result))super.onBackPressed();});else super.onBackPressed();}
}
